<header class="page-hero compact shell"><span class="eyebrow">CONTUL MEU</span><h1>Adrese</h1></header><div class="account-layout shell"><?php require BASE_PATH.'/views/components/account-nav.php';?><section class="account-content"><div class="address-grid"><?php foreach($addresses as $address):?><article class="address-card"><?php if($address['is_default']):?><span class="status-badge">Implicită</span><?php endif?><h2><?=e($address['label'])?></h2><p><?=e($address['first_name'].' '.$address['last_name'])?><br><?=e($address['address'])?><br><?=e($address['city'].', '.$address['county'].' '.$address['postcode'])?><br><?=e($address['phone'])?></p></article><?php endforeach?></div><form class="card-form" action="/cont/adrese" method="post"><?=csrf_field()?><h2>Adaugă o adresă</h2><div class="form-grid"><label>Etichetă<input name="label" value="Acasă"></label><label>Prenume<input name="first_name" value="<?=e(user()['first_name'])?>" required></label><label>Nume<input name="last_name" value="<?=e(user()['last_name'])?>" required></label><label>Telefon<input name="phone" value="<?=e(user()['phone'])?>"></label><label>Județ<input name="county" required></label><label>Localitate<input name="city" required></label><label class="span-2">Adresă<input name="address" required></label><label>Cod poștal<input name="postcode"></label></div><label class="check"><input type="checkbox" name="is_default" value="1"> Adresă implicită</label><button class="button" type="submit">SALVEAZĂ ADRESA</button></form></section></div>
